insert into public.plan_exercises(id,name,grp,how_to,dose,progression,caution) values
('AK01','Ankle pump dan alfabet','Mobilitas/sirkulasi','Gerakkan pergelangan naik-turun, atau tulis huruf A-Z dengan ujung kaki.','10 kali x 3-4/hari',null,'Tanpa nyeri tajam.'),
