-- Daftar exercise Plan SOAP (dari Plan_Exercise_Kaffah_329_Diagnosa.xlsx): 213 latihan, 329 diagnosa x 3 fase.
create table if not exists public.plan_exercises (
  id text primary key, name text not null, grp text, how_to text, dose text, progression text, caution text
);
create table if not exists public.diagnosis_exercise_plans (
  diagnosis_key text primary key, display_name text not null, service text, icd10 text,
  phase1 text[] not null default '{}', phase2 text[] not null default '{}', phase3 text[] not null default '{}', caution text
);
alter table public.plan_exercises enable row level security;
alter table public.diagnosis_exercise_plans enable row level security;
create policy "plan_exercises_read" on public.plan_exercises for select to authenticated using (true);
create policy "diagnosis_exercise_plans_read" on public.diagnosis_exercise_plans for select to authenticated using (true);
create policy "plan_exercises_write" on public.plan_exercises for all to authenticated
  using (public.get_my_role() = 'super_admin') with check (public.get_my_role() = 'super_admin');
create policy "diagnosis_exercise_plans_write" on public.diagnosis_exercise_plans for all to authenticated
  using (public.get_my_role() = 'super_admin') with check (public.get_my_role() = 'super_admin');

on conflict (id) do nothing;

on conflict (diagnosis_key) do nothing;
